#include <atomic>
#include <iostream>
#include <thread>

int data = 0;
std::atomic<bool> ready{false};

int main() {
  std::thread writer([] {
    data = 42;
    ready.store(true, std::memory_order_release);
  });

  std::thread reader([] {
    while (!ready.load(std::memory_order_acquire)) {}
    std::cout << data;
  });

  writer.join();
  reader.join();
}
